import { Parameters, Questionnaire, ParametersParameter, OperationOutcome } from 'fhir/r4';

/**
 * Input parameters for the $assemble operation
 * @see {@link http://hl7.org/fhir/uv/sdc/OperationDefinition/Questionnaire-assemble}
 *
 * @author Sean Fong
 */
interface InputParameters extends Parameters {
    parameter: [
        {
            name: 'questionnaire';
            resource: Questionnaire;
        }
    ];
}
/**
 * Output parameters for the $assemble operation
 * @see {@link http://hl7.org/fhir/uv/sdc/OperationDefinition/Questionnaire-assemble}
 *
 * @author Sean Fong
 */
interface OutputParameters extends Parameters {
    parameter: [ReturnParameter, OutcomeParameter];
}
interface ReturnParameter extends ParametersParameter {
    name: 'return';
    resource: Questionnaire;
}
/**
 * Output parameter from $assemble's 'outcome' parameter
 * @see {@link http://hl7.org/fhir/uv/sdc/OperationDefinition/Questionnaire-assemble}
 *
 * @author Sean Fong
 */
interface OutcomeParameter extends ParametersParameter {
    name: 'outcome';
    resource: OperationOutcome;
}

/**
 * To define a method to fetch Questionnaire resources from the FHIR server with the given canonical URL
 * @see {@link https://www.hl7.org/fhir/questionnaire.html}
 *
 * @param canonicalUrl - The canonical URL of the Questionnaire resource
 * @param requestConfig - Any kind of request configuration necessary (auth, token, etc)
 * @returns A promise of the Questionnaire Bundle resource (or an error)!
 *
 * @example
 * const fetchQuestionnaireCallback: FetchQuestionnaireCallback = async (
 *   canonicalUrl: string,
 *   requestConfig: {url: string, authToken?: string}
 * ) => {
 *   const { url, authToken } = requestConfig;
 *
 *   let requestUrl = url;
 *   if (!requestUrl.endsWith('/')) {
 *     requestUrl += '/';
 *   }
 *   requestUrl += `Questionnaire?url=${canonicalUrl}`;
 *
 *   const headers = authToken ? { ...HEADERS, Authorization: `Bearer ${authToken}` } : HEADERS;
 *
 *   const response = await fetch(requestUrl, {
 *     headers: headers
 *   });
 *
 *   if (!response.ok) {
 *     throw new Error(`HTTP error when performing ${requestUrl}. Status: ${response.status}`);
 *   }
 *
 *   return response.json();
 * };
 *
 * @author Sean Fong
 */
interface FetchQuestionnaireCallback {
    (canonicalUrl: string, requestConfig?: any): Promise<any>;
}

/**
 * Check if the given parameters is a valid InputParameters for $assemble
 * @see {@link http://hl7.org/fhir/uv/sdc/OperationDefinition/Questionnaire-assemble}
 *
 * @param parameters - a given Parameters resource
 * @return boolean value of whether the given parameters is InputParameters
 *
 * @author Sean Fong
 */
declare function isInputParameters(parameters: Parameters): parameters is InputParameters;

/**
 * The $assemble operation - https://build.fhir.org/ig/HL7/sdc/OperationDefinition-Questionnaire-assemble.html
 *
 * @param parameters - The input parameters for $assemble
 * @param fetchQuestionnaireCallback - A callback function defined by the implementer to fetch Questionnaire resources by a canonical url
 * @param fetchQuestionnaireRequestConfig - A request configuration object to be passed to the callback function
 * @returns A fully assembled questionnaire, an operationOutcome error(if present) or both (if there are warnings)
 *
 * @author Sean Fong
 */
declare function assemble(parameters: InputParameters, fetchQuestionnaireCallback: FetchQuestionnaireCallback, fetchQuestionnaireRequestConfig: any): Promise<Questionnaire | OperationOutcome | OutputParameters>;

export { type FetchQuestionnaireCallback, type InputParameters, type OutcomeParameter, type OutputParameters, assemble, isInputParameters };
